// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"Statistics is the science of learning from data. It starts with knowing what kind of data you have.","blocks":[{"t":"p","text":"Categorical data puts individuals into groups (favorite sport); quantitative data are numbers you can average (height). Displays:"},{"t":"list","items":["Categorical: bar graphs and pie charts.","Quantitative: dotplots, histograms, stemplots and boxplots."]},{"t":"key","text":"Describe a distribution's shape (symmetric, skewed left or right), center, spread and any outliers."},{"t":"p","text":"A distribution is skewed right if it has a long tail to the right (like incomes). It's skewed left if the tail is on the left."},{"t":"tip","text":"Ask \"Does it make sense to average this?\" If yes, it's quantitative. Zip codes are numbers, but averaging them is meaningless, so they're categorical."}]},{"say":"Two numbers summarize most data sets: where the center is and how spread out values are.","blocks":[{"t":"key","text":"Mean = average; median = middle value. Range = max − min. IQR = Q3 − Q1. Standard deviation measures typical distance from the mean."},{"t":"p","text":"The five-number summary (min, Q1, median, Q3, max) is shown by a boxplot. Outliers fall below Q1 − 1.5·IQR or above Q3 + 1.5·IQR."},{"t":"ex","problem":"Data: 2, 4, 5, 7, 9, 10, 30. Find the median and check if 30 is an outlier.","steps":["Median: 7. Q1 = 4, Q3 = 10, IQR = 6","Upper fence: 10 + 1.5(6) = 19"],"answer":"Median 7; 30 is an outlier"},{"t":"p","text":"Use median and IQR for skewed data; use mean and standard deviation for symmetric data."}]}],[{"say":"The bell-shaped normal curve appears everywhere in nature. z-scores let us compare values on it.","blocks":[{"t":"key","text":"z = (x − mean) ÷ standard deviation. It tells how many standard deviations a value is from the mean."},{"t":"p","text":"Empirical rule: in a normal distribution, about 68% of data is within 1 standard deviation, 95% within 2, and 99.7% within 3."},{"t":"ex","problem":"Heights have mean 66 in and standard deviation 3 in. What percent are between 60 and 72 inches?","steps":["60 and 72 are 2 standard deviations from the mean"],"answer":"about 95%"},{"t":"p","text":"z-scores let you compare apples and oranges: a test score with z = 1.5 is more impressive than one with z = 0.8, even on different tests."}]},{"say":"Percentiles and z-scores answer questions like \"How does my score compare to everyone else's?\"","blocks":[{"t":"p","text":"A percentile is the percent of values at or below a given value. Scoring at the 90th percentile means you did as well as or better than 90% of test takers."},{"t":"key","text":"In a normal distribution, z = 1 is about the 84th percentile, z = 2 is about the 97.5th percentile, and z = −1 is about the 16th percentile."},{"t":"ex","problem":"Ana scored 85 on a test with mean 75 and SD 5. Ben scored 90 on a test with mean 80 and SD 10. Who did better relative to their class?","steps":["Ana: z = (85 − 75)/5 = 2","Ben: z = (90 − 80)/10 = 1"],"answer":"Ana did better relative to her class"}]}],[{"say":"Do two variables move together? Scatterplots let us see the relationship, and correlation measures it.","blocks":[{"t":"p","text":"A scatterplot graphs pairs of quantitative data. Describe its direction (positive or negative), form (linear or curved) and strength."},{"t":"key","text":"The correlation coefficient r is between −1 and 1. Values near ±1 mean a strong linear relationship; near 0 means weak or none."},{"t":"oops","text":"Correlation is not causation. Ice cream sales and sunburns are correlated because both increase in summer; ice cream doesn't cause sunburn."},{"t":"p","text":"A lurking variable is a hidden variable that affects both variables in a relationship."}]},{"say":"A regression line is the best-fitting line through a scatterplot. It helps us make predictions.","blocks":[{"t":"key","text":"The least-squares regression line is ŷ = a + bx. The slope b tells the predicted change in y for each one-unit increase in x."},{"t":"p","text":"A residual is actual − predicted. Positive residuals mean the point is above the line."},{"t":"ex","problem":"ŷ = 20 + 5x predicts a test score from hours studied. Predict the score for 6 hours and interpret the slope.","steps":["ŷ = 20 + 5(6) = 50"],"answer":"Predicted score 50; each extra hour of study predicts 5 more points"},{"t":"oops","text":"Don't extrapolate far beyond the data. Predicting a score for 40 hours of study would be unreliable."},{"t":"p","text":"r² tells the percent of variation in y explained by the line."}]}],[{"say":"How data is collected determines whether it can be trusted. Let's learn to spot good and bad studies.","blocks":[{"t":"p","text":"A population is the whole group; a sample is the part studied. A random sample gives every individual an equal chance of selection, reducing bias."},{"t":"key","text":"Biased samples (voluntary response, convenience) don't represent the population, even if they're large."},{"t":"p","text":"In an observational study, researchers observe without intervening. In an experiment, they impose treatments. Only randomized experiments can show cause and effect."},{"t":"p","text":"Good experiments use a control group, random assignment, and enough subjects (replication). Blinding prevents expectations from affecting results."}]},{"say":"Probability gives us a language for chance. A few rules handle most situations.","blocks":[{"t":"key","text":"P(A) is between 0 and 1. P(not A) = 1 − P(A). For independent events, P(A and B) = P(A) × P(B). P(A or B) = P(A) + P(B) − P(A and B)."},{"t":"ex","problem":"Draw a card from a standard deck. P(king or heart)?","steps":["P(king) = 4/52, P(heart) = 13/52, P(king of hearts) = 1/52","4/52 + 13/52 − 1/52"],"answer":"16/52 = 4/13"},{"t":"p","text":"Conditional probability P(A | B) is the probability of A given that B happened. Two-way tables help compute it."}]}],[{"say":"We almost never know the true value for a whole population. Confidence intervals give a range of plausible values.","blocks":[{"t":"key","text":"Confidence interval = estimate ± margin of error. A 95% confidence level means that if we repeated the sampling many times, about 95% of intervals would capture the true value."},{"t":"ex","problem":"A poll finds 54% support a policy with a margin of error of ±3%. Interpret it.","steps":["Interval: 51% to 57%"],"answer":"We're 95% confident the true support is between 51% and 57%"},{"t":"p","text":"Larger samples give smaller margins of error. Higher confidence levels give wider intervals."}]},{"say":"A hypothesis test asks whether data provides convincing evidence against a claim.","blocks":[{"t":"key","text":"The null hypothesis (H₀) states no effect or no difference. The alternative hypothesis (Hₐ) is what we suspect. A small P-value (usually less than 0.05) is evidence against H₀."},{"t":"p","text":"The P-value is the probability of getting results as extreme as ours if H₀ were true."},{"t":"ex","problem":"A coin is flipped 100 times and lands heads 70 times. A test of H₀: the coin is fair gives a P-value of 0.0001. Conclusion?","steps":["P-value < 0.05"],"answer":"Reject H₀; there is strong evidence the coin is not fair"},{"t":"p","text":"Errors: a Type I error rejects a true H₀; a Type II error fails to reject a false H₀."}]}]];
export default text;
